# Simple heuristic for language detection: the presence of any CJK character
# means the question is treated as Chinese, otherwise English is assumed.
_CJK_RE = re.compile(r"[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]")

# Languages the planner may route to.
SUPPORTED_LANGUAGES = ("en", "zh")

# Answer types understood by the planner.
EXPECTED_ANSWER_TYPES = ("short_fact", "list_of_facts", "long_explanation")

# Answer types that always imply the search tool must be consulted.
FACT_SEEKING_ANSWER_TYPES = ("short_fact", "list_of_facts")

# Tokens that make an explicit search intent detectable inside a sub-question.
SEARCH_INTENT_TOKENS = [secret redacted]

# A sub-question quality heuristic: at least this many characters and at least
# one alphabetic or CJK character.
_MIN_SUBQUESTION_LEN = 8
_ALPHA_OR_CJK_RE = re.compile(
    r"[A-Za-z\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]"
)


def detect_language(text: Optional[str]) -> str:
    """Return ``"zh"`` when ``text`` contains CJK characters, else ``"en"``."""
    if text and _CJK_RE.search(text):
        return "zh"
    return "en"


def _has_cjk(text: str) -> bool:
    return bool(_CJK_RE.search(text or ""))


def _detect_primary_language(text: Optional[str]) -> str:
    """Choose a single primary language for a (possibly mixed) prompt.

    A code-mixed prompt is still assigned exactly one primary language: the
    language that contributes the majority of alphabetic/CJK characters.  Ties
    fall back to the CJK-first heuristic used by :func:`detect_language`.
    """
    if not text:
        return "en"
    cjk = len(_CJK_RE.findall(text))
    latin = len(re.findall(r"[A-Za-z]", text))
    if cjk > 0 and cjk >= latin:
        return "zh"
    if latin > 0 and latin > cjk:
        return "en"
    return detect_language(text)


def _coalesce(*values: Any) -> Any:
    """Return the first non-``None`` value, or ``None`` if all are ``None``."""
    for value in values:
        if value is not None:
            return value
    return None


class PlanningError(Exception):
    """Raised when the deep-research model does not return a valid plan."""


def _extract_text(response: Any) -> str:
    """Best-effort extraction of a text payload from an LLM response.

    Supports plain strings, ``{"content": ...}``/``{"text": ...}`` mappings and
    objects exposing a ``content``/``text`` attribute, so the planner works
    with a range of client shapes without any network access.
    """
    if response is None:
        return ""
    if isinstance(response, str):
        return response
    if isinstance(response, dict):
        for key in ("content", "text", "response", "output", "message"):
            [secret redacted]
                return _extract_text(response[key])
        return json.dumps(response)
    if isinstance(response, (list, tuple)):
        return "".join(_extract_text(item) for item in response)
    for attr in ("content", "text", "response", "output"):
        value = getattr(response, attr, None)
        if value is not None:
            return _extract_text(value)
    return str(response)


def _call_llm(client: Any, system_prompt: str, user_prompt: str) -> str:
    """Invoke an injected LLM client and return its text response.

    The call is deliberately generic so that any thin client wrapper (with a
    ``complete``/``generate``/``chat`` method, or a plain callable) works.  No
    network access happens here beyond what the injected client itself does.
    """
    if client is None:
        raise PlanningError("no deep-research LLM client was injected")

    for method_name in ("complete", "generate", "chat", "invoke", "create"):
        method = getattr(client, method_name, None)
        if callable(method):
            return _extract_text(
                method(system_prompt=system_prompt, user_prompt=user_prompt)
            )

    if callable(client):
        return _extract_text(
            client(system_prompt=system_prompt, user_prompt=user_prompt)
        )

    raise PlanningError("injected LLM client exposes no callable interface")


def _strip_code_fences(text: str) -> str:
    """Remove an optional ```json ... ``` fence surrounding a JSON payload."""
    stripped = (text or "").strip()
    if stripped.startswith("```"):
        stripped = re.sub(r"^```[A-Za-z0-9_-]*\s*", "", stripped)
        stripped = re.sub(r"\s*```$", "", stripped)
    return stripped.strip()


def _parse_plan_json(text: str) -> Dict[str, Any]:
    """Parse a strict-JSON plan, raising :class:`PlanningError` on failure."""
    payload = _strip_code_fences(text)
    if not payload:
        raise PlanningError("empty plan response from the deep-research model")
    try:
        parsed = json.loads(payload)
    except (ValueError, TypeError) as exc:  # malformed JSON / not a string
        raise PlanningError(f"plan response is not valid JSON: {exc}") from exc
    if not isinstance(parsed, dict):
        raise PlanningError("plan response JSON is not an object")
    return parsed

