def _parse_plan_json(text: str) -> Dict[str, Any]:
    """Parse a strict-JSON plan, raising :class:`PlanningError` on failure."""
    payload = _strip_code_fences(text)
    if not payload:
        raise PlanningError("empty plan response from the deep-research model")
    try:
        parsed = json.loads(payload)
    except (ValueError, TypeError) as exc:  # malformed JSON / not a string
        raise PlanningError(f"plan response is not valid JSON: {exc}") from exc
    if not isinstance(parsed, dict):
        raise PlanningError("plan response JSON is not an object")
    return parsed


def _is_quality_subquestion(value: Any) -> bool:
    """Return ``True`` when ``value`` passes the sub-question heuristic."""
    if not isinstance(value, str):
        return False
    text = value.strip()
    return len(text) >= _MIN_SUBQUESTION_LEN and bool(_ALPHA_OR_CJK_RE.search(text))


def _has_search_intent(text: str) -> bool:
    lowered = (text or "").lower()
    return any(token in lowered for token in SEARCH_INTENT_TOKENS)


def _search_ready_query(question: str, language: str) -> str:
    """Build a guaranteed search-intent sub-question from ``question``."""
    question = (question or "").strip() or "the research topic"
    if language == "zh":
        return f"使用搜索工具查找: {question}"
    return f"web search for: {question}"


def _normalise_plan(
    raw: Dict[str, Any], question: str, must_use_search: bool
) -> Dict[str, Any]:
    """Validate and normalise a raw plan into the documented contract.

    Ensures the four required fields are present and well-typed, enforces the
    search-intent and must-search rules, and always returns a usable plan.
    """
    if not isinstance(raw, dict):
        raise PlanningError("plan must be a JSON object")

    # --- target language --------------------------------------------------
    target_language = raw.get("target_language")
    if target_language not in SUPPORTED_LANGUAGES:
        target_language = _detect_primary_language(question)

    # --- sub-questions ----------------------------------------------------
    raw_subquestions = raw.get("subquestions")
    if isinstance(raw_subquestions, str):
        raw_subquestions = [raw_subquestions]
    if not isinstance(raw_subquestions, (list, tuple)):
        raw_subquestions = []
    subquestions: List[str] = []
    for item in raw_subquestions:
        if isinstance(item, str):
            text = item.strip()
            if _is_quality_subquestion(text):
                subquestions.append(text)
    if not subquestions:
        subquestions.append((question or "the research topic").strip())

    if not any(_has_search_intent(sq) for sq in subquestions):
        subquestions.append(_search_ready_query(question, target_language))

    # --- answer type ------------------------------------------------------
    expected_answer_type = raw.get("expected_answer_type")
    if expected_answer_type not in EXPECTED_ANSWER_TYPES:
        expected_answer_type = "long_explanation"

    # --- must search ------------------------------------------------------
    must_search = raw.get("must_search")
    if not isinstance(must_search, bool):
        must_search = bool(must_use_search)
    if expected_answer_type in FACT_SEEKING_ANSWER_TYPES:
        must_search = True
    if must_use_search:
        must_search = True

    plan: Dict[str, Any] = {
        "target_language": target_language,
        "subquestions": subquestions,
        "expected_answer_type": expected_answer_type,
        "must_search": must_search,
    }

    notes = raw.get("notes")
    if isinstance(notes, str) and notes.strip():
        plan["notes"] = notes.strip()

    return plan

