def _maybe_resolve(value: Any) -> Any:
    """Resolve ``value`` to a concrete result, awaiting it if necessary.

    Tool collaborators may be synchronous (plain functions / mocks) or
    asynchronous (the real ``SearchEngineTool``/``BrowsingAgent`` are async).
    This helper transparently awaits coroutines so the synchronous research
    flow keeps working with either flavour, without performing any network
    access of its own.
    """
    if not inspect.isawaitable(value):
        return value
    try:
        return asyncio.run(value)
    except RuntimeError:
        # A loop is already running in this thread; drive the coroutine on a
        # fresh loop so callers are never blocked by nested-loop errors.
        loop = asyncio.new_event_loop()
        try:
            return loop.run_until_complete(value)
        finally:
            loop.close()


