def _search_succeeded(raw: Any) -> bool:
    """Return ``True`` when a search call produced a usable response.

    An ``None`` result or an explicitly empty result list is treated as a
    failure so :meth:`ResearchAgent.run` can report a retrieval failure.  An
    opaque object (for example a lightweight mock) is assumed to be a
    successful call so the skeleton stays backward compatible.
    """
    if raw is None:
        return False
    if isinstance(raw, (list, tuple)):
        return len(raw) > 0
    if isinstance(raw, dict):
        return bool(_normalise_search_results(raw))
    return True


def _normalise_browse_snippets(raw: Any) -> List[str]:
    """Normalise a browsing-agent response into a list of non-empty snippets."""
    if raw is None:
        return []
    if isinstance(raw, str):
        text = raw.strip()
        return [text] if text else []
    if isinstance(raw, dict):
        snippets: List[str] = []
        for key in (
            "snippets",
            "useful_information",
            "content",
            "text",
            "answer",
            "result",
            "summary",
        ):
            value = raw.get(key)
            if isinstance(value, str) and value.strip():
                snippets.append(value.strip())
            elif isinstance(value, (list, tuple)):
                snippets.extend(
                    v.strip() for v in value if isinstance(v, str) and v.strip()
                )
        if not snippets:
            for value in raw.values():
                if isinstance(value, str) and value.strip():
                    snippets.append(value.strip())
        return snippets
    if isinstance(raw, (list, tuple)):
        collected: List[str] = []
        for item in raw:
            collected.extend(_normalise_browse_snippets(item))
        return collected
    text = str(raw).strip()
    return [text] if text else []


