def _insufficient_evidence_answer(language: str, truncated: bool = False) -> str:
    """Return a citation-free answer that explicitly admits limited evidence."""
    if language == "zh":
        answer = INSUFFICIENT_EVIDENCE_ANSWER_ZH
        if truncated:
            answer += " 证据收集在时间预算内被提前截断。"
        return answer
    answer = INSUFFICIENT_EVIDENCE_ANSWER_EN
    if truncated:
        answer += (
            " Evidence gathering was truncated before the research time budget "
            "was exhausted."
        )
    return answer


def _numbered_evidence(evidence: Any) -> List[Dict[str, Any]]:
    """Assign stable ``S1``, ``S2``, ... identifiers to evidence items.

    Only real dict items are numbered; the ids are contiguous so a
    ``[S<n>]`` citation always maps back to the same evidence entry.
    """
    if not isinstance(evidence, dict):
        return []
    items = evidence.get("items")
    if not isinstance(items, list):
        items = evidence.get("results")
    if not isinstance(items, list):
        return []

    numbered: List[Dict[str, Any]] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        snippets = [
            s for s in (item.get("snippets") or []) if isinstance(s, str) and s
        ]
        numbered.append(
            {
                "id": f"S{len(numbered) + 1}",
                "url": item.get("url", "") if isinstance(item.get("url"), str) else "",
                "title": item.get("title", "")
                if isinstance(item.get("title"), str)
                else "",
                "language": item.get("language", "")
                if isinstance(item.get("language"), str)
                else "",
                "snippets": snippets,
            }
        )
    return numbered


def _format_evidence_block(numbered: List[Dict[str, Any]]) -> str:
    """Render numbered evidence items into a compact text block for the LLM."""
    lines: List[str] = []
    for item in numbered:
        header = f"[{item['id']}]"
        if item.get("title"):
            header += f" {item['title']}"
        if item.get("url"):
            header += f" ({item['url']})"
        lines.append(header)
        if item.get("language"):
            lines.append(f"language: {item['language']}")
        for snippet in item.get("snippets", []):
            lines.append(f"- {snippet}")
        lines.append("")
    return "\n".join(lines).strip()


def _extract_citation_ids(text: str) -> List[str]:
    """Return the citation ids referenced in ``text``, in first-seen order."""
    ids: List[str] = []
    for match in CITATION_RE.finditer(text or ""):
        sid = f"S{int(match.group(1))}"
        if sid not in ids:
            ids.append(sid)
    return ids


def _sanitise_citations(text: str, known_ids: set) -> str:
    """Strip any citation marker that does not correspond to real evidence."""

    def _replace(match: "re.Match[str]") -> str:
        sid = f"S{int(match.group(1))}"
        return match.group(0) if sid in known_ids else ""

    return CITATION_RE.sub(_replace, text or "").strip()


